@router.post('/api/exports/{export_id}/webhook')
async def configure_export_webhook(
    export_id: int,
    payload: WebhookConfigRequest,
    user: User = Depends(get_current_user)
):
    job = await ExportJob.get_or_none(id=export_id, requester_id=user.id)
    if not job:
        raise HTTPException(status_code=404, detail="Export job not found")

    job.callback_webhook_url = str(payload.url)
    await job.save()
    return {"status": "webhook configured", "webhook": job.callback_webhook_url}
